package com.app.templatestudio;
import java.io.*;import java.util.*;import java.util.zip.*;import javax.xml.XMLConstants;import javax.xml.parsers.DocumentBuilderFactory;import org.springframework.stereotype.Component;import org.w3c.dom.*;
@Component public class TemplateDefinitionMapper{
 public Map<String,Object> map(byte[] zipBytes){try{Map<String,byte[]> files=new HashMap<>();try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(zipBytes))){ZipEntry e;while((e=z.getNextEntry())!=null){if(e.getName().equals("template.xml")||e.getName().equals("preview.xml")){ByteArrayOutputStream o=new ByteArrayOutputStream();z.transferTo(o);files.put(e.getName(),o.toByteArray());}z.closeEntry();}}
 Element root=parse(files.get("template.xml")).getDocumentElement(),sample=parse(files.get("preview.xml")).getDocumentElement();List<Map<String,Object>> sections=new ArrayList<>(),sampleSections=new ArrayList<>();NodeList ss=root.getElementsByTagName("section");
 for(int i=0;i<ss.getLength();i++){Element s=(Element)ss.item(i);String key=req(s,"key");List<Map<String,Object>> fields=new ArrayList<>();List<String> required=new ArrayList<>();Map<String,Object> values=new LinkedHashMap<>();boolean repeat=false;NodeList fs=s.getElementsByTagName("field");
 for(int j=0;j<fs.getLength();j++){Element f=(Element)fs.item(j);String fk=req(f,"key"),type=req(f,"type");boolean r=Boolean.parseBoolean(f.getAttribute("required"));repeat|=Boolean.parseBoolean(f.getAttribute("repeatable"))||type.equals("repeatable");Map<String,Object> fm=new LinkedHashMap<>();fm.put("key",fk);fm.put("label",req(f,"label"));fm.put("type",type.equals("longtext")?"textarea":type.equals("phone")?"tel":type.equals("location")?"address":type.equals("repeatable")?"text":type);fm.put("required",r);fm.put("placeholder",f.getAttribute("placeholder"));fields.add(fm);if(r)required.add(fk);NodeList val=sample.getElementsByTagName(fk);if(val.getLength()>0&&!val.item(0).getTextContent().isBlank())values.put(fk,val.item(0).getTextContent().trim());}
 boolean optional=Boolean.parseBoolean(s.getAttribute("optional"));Map<String,Object> sm=new LinkedHashMap<>();sm.put("key",key);sm.put("label",req(s,"label"));sm.put("enabled",true);sm.put("required",!optional);sm.put("optional",optional);sm.put("repeatable",repeat);sm.put("fields",fields);sm.put("requiredFields",required);sections.add(sm);Map<String,Object> sc=new LinkedHashMap<>();sc.put("key",key);sc.put("enabled",true);sc.put("values",values);if(repeat)sc.put("items",List.of(values));sampleSections.add(sc);}
 Map<String,Object>d=new LinkedHashMap<>();d.put("schemaVersion",1);d.put("templateId",req(root,"id"));d.put("name",req(root,"name"));d.put("version",req(root,"version"));d.put("sections",sections);Map<String,Object> out=new LinkedHashMap<>();out.put("definition",d);out.put("sampleContent",Map.of("sections",sampleSections));out.put("title",req(root,"name"));return out;
 }catch(Exception e){throw new IllegalArgumentException("Unable to map template XML",e);}}
 private Document parse(byte[] xml)throws Exception{if(xml==null)throw new IllegalArgumentException("Missing XML file");DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);f.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD,"");f.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");f.setXIncludeAware(false);f.setExpandEntityReferences(false);return f.newDocumentBuilder().parse(new ByteArrayInputStream(xml));}
 private String req(Element e,String a){String v=e.getAttribute(a).trim();if(v.isEmpty())throw new IllegalArgumentException("Missing XML attribute "+a);return v;}
}